const ahora = new Date();
const ts = Date.now();

const fecha = ahora
  .toISOString()
  .slice(0, 19)
  .replace('T', ' ');

return [
  {
    json: {
      id_ejecucion: 'COM-SIN-' + ts,
      id_incidente: 'INC-COM-' + ts,

      flujo: '04',
      proceso: 'comunicados',
      escenario: 'sin_seguridad',
      bloque: 'sin_seguridad',

      asunto: 'Comunicado institucional de prueba',
      emisor: 'direccion.general@instituto.edu.pe',
      destinatario: 'estudiantes@instituto.edu.pe',
      cuerpo: 'Se comunica a los estudiantes que las actividades académicas continuarán con normalidad.',

      estado_comunicado: 'enviado',
      hora_ingreso: fecha
    }
  }
];

return items.map(item => {

  const datos = item.json;

  // Escenario SIN seguridad:
  // solo se realiza el procesamiento funcional del comunicado.
  // No se aplican controles SOAR, score de riesgo,
  // bloqueo ni respuesta automática de seguridad.

  const completo = Boolean(
    datos.asunto &&
    datos.emisor &&
    datos.destinatario &&
    datos.cuerpo
  );

  datos.estado_comunicado = completo
    ? 'enviado'
    : 'cancelado';

  datos.estado_ejecucion = completo
    ? 'success'
    : 'error';

  datos.categoria_sistema = 'comunicado_institucional';
  datos.categoria_real = 'comunicado_institucional';
  datos.clasificacion_correcta = true;

  datos.hora_procesamiento = new Date()
    .toISOString()
    .slice(0, 19)
    .replace('T', ' ');

  return item;
});
